function C:SetUserName()
  self._userText.text = ((function() if self.tweetDrawable.IsOmote then return NgoEx.SystemTextFromType("Account_Omote", Settings.CurrentLanguage.Value) else return NgoEx.SystemTextFromType("Account_Ura_Name", Settings.CurrentLanguage.Value) end end)())
  return not STR.IsNullOrEmpty(self._userText.text)
end

function C:FetchBody()
  self._bodyText.text = NgoEx.GetTweetBody(self.tweetDrawable, Settings.CurrentLanguage.Value)
end

function C:FetchTweetImage()
  if not coroutine.isyieldable() then spawn(C.FetchTweetImage, self) return end
  local hasImage = NgoEx.IsNotEmpty(self.tweetDrawable.ImageId)
  self._image.gameObject:SetActive(hasImage)
  if hasImage then
    local imageId = self.tweetDrawable.ImageId
    local resource = self._resourceMaster.ResourceList:FirstOrDefault(function(r) return r.FileName == imageId end)
    if resource == nil then
      Debug.Log(CONCAT("TWEET MASTERリソースがないよ！:", imageId))
      self._image.gameObject:SetActive(false)
      return false
    end
    Settings:addImage(imageId, true)
    local sprite = LoadPictures.LoadPictureAsync(resource.FileName, "Poketter")
    self._image.sprite = sprite
    self._imageFileName = resource.FileName
    if imageId == "MV_thumbnail" then
      self.imageButton.onClick:AddListener(function()
        self:PlayMV()
      end)
      return true
    end
    self.imageButton.onClick:AddListener(function()
      spawn(function() ImageViewerHelper.OpenImageViewer(resource.FileName) end)
    end)
  end
  return hasImage
end

function C:PlayMV()
  if not coroutine.isyieldable() then spawn(C.PlayMV, self) return end
  self.imageButton.enabled = false
  ShortcutInputManager:ChangeControllerMode("MV_Playing")
  local videoViewer = GameObject.Find("Main Camera"):GetComponent("VideoPlayer")
  videoViewer.clip = Resources.Load("VideoClip", "Videos/INTERNETOVERDOSE")
  videoViewer:Prepare()
  UniTask.WaitUntil(function() return videoViewer.isPrepared end, "Update", self:GetCancellationTokenOnDestroy(), false)
  videoViewer.aspectRatio = "FitInside"
  videoViewer:SetDirectAudioVolume(0, Settings.BgmVolume)
  AudioManager:StopBgm()
  videoViewer.targetCameraAlpha = 1
  videoViewer:Play()
  NgoEvent.DelaySkippable(2000)
  AudioManager:PlayBgmByType("BGM_InternetOverdose", false)
  UniTask.WhenAny(NgoEvent.DelaySkippable(224000), UniTask.WaitUntil(function() return ShortcutInputManager.Player:GetButtonDown("StopPlaying") end, "Update", nil, false))
  videoViewer.targetCameraAlpha = 0
  videoViewer:Stop()
  AudioManager:PlayBgmByType("BGM_InternetOverdose8bit", true)
  videoViewer.aspectRatio = "FitHorizontally"
  self.imageButton.enabled = true
  ShortcutInputManager:ChangeControllerMode("Desktop")
end

function C:Show()
  if not coroutine.isyieldable() then spawn(C.Show, self) return end
  self.fader:SetAlpha(0)
  local component = self:GetComponent("RectTransform")
  component.localScale = NEW("Vector3", nil, 1, 0, 1)
  local duration = self._scrollMillisecond / 1000
  component:DOScaleY(1, duration):Play()
  self.fader:DOFade_1(1, 1)
  NgoEvent.DelaySkippable(STR.Length(self._bodyText.text) * 10)
end

function C:ConvertGigaNumber(number)
  if number > 1000000000 then
    return (TOSTR(IDIV(number, 100000000)) .. "G")
  end
  if number > 1000000 then
    return (TOSTR(IDIV(number, 100000)) .. "M")
  end
  if number > 10000 then
    return (TOSTR(IDIV(number, 1000)) .. "K")
  end
  return TOSTR(number)
end

function C:FavRtMove()
